#!/bin/bash
# ==============================================================================
# HOMESEVA DATABASE RESTORE UTILITY
# Restores a PostgreSQL backup (.dump) generated by db-backup.sh
# Usage:
#   bash scripts/db-restore.sh /backups/homeseva/homeseva_weekly_YYYYMMDD_HHMMSS.dump
# ==============================================================================

set -euo pipefail

if [ $# -lt 1 ]; then
  echo "Usage: $0 <path-to-dump-file>"
  echo "Example: $0 /backups/homeseva/homeseva_weekly_20261122_020000.dump"
  exit 1
fi

DUMP_FILE="$1"

if [ ! -f "$DUMP_FILE" ]; then
  echo "❌ Error: Backup file not found: $DUMP_FILE"
  exit 1
fi

# 1. Verify SHA-256 Checksum if present
if [ -f "${DUMP_FILE}.sha256" ]; then
  echo "🔍 Verifying SHA-256 checksum..."
  if sha256sum -c "${DUMP_FILE}.sha256"; then
    echo "✅ Checksum verification passed (file is intact and uncorrupted)."
  else
    echo "❌ Error: SHA-256 Checksum verification failed! File may be corrupt."
    exit 1
  fi
else
  echo "⚠️ Warning: No .sha256 file found. Proceeding without checksum verification."
fi

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"

if [ -f "$PROJECT_DIR/.env" ]; then
  set -a
  # shellcheck disable=SC1091
  source "$PROJECT_DIR/.env"
  set +a
fi

DB_NAME="${POSTGRES_DB:-homeseva_db}"
DB_USER="${POSTGRES_USER:-homeseva}"
DB_PASS="${POSTGRES_PASSWORD:-}"
DB_HOST="${POSTGRES_HOST:-localhost}"
DB_PORT="${POSTGRES_PORT:-5432}"

echo "================================================================="
echo "⚠️  WARNING: You are about to restore into database: ${DB_NAME}"
echo "    This will replace existing tables with data from the backup."
echo "================================================================="
read -rp "Are you sure you want to proceed with restore? [y/N]: " CONFIRM
if [[ ! "$CONFIRM" =~ ^[Yy]$ ]]; then
  echo "Restore aborted by user."
  exit 0
fi

echo "🚀 Starting database restore from: $DUMP_FILE..."

if docker ps --format '{{.Names}}' | grep -q "homeseva_postgres"; then
  echo "Restoring via homeseva_postgres container..."
  docker exec -i homeseva_postgres pg_restore -U "$DB_USER" -d "$DB_NAME" --clean --if-exists < "$DUMP_FILE" || true
elif [ -n "$DB_PASS" ]; then
  echo "Restoring via host connection..."
  PGPASSWORD="$DB_PASS" pg_restore \
    -h "$DB_HOST" \
    -p "$DB_PORT" \
    -U "$DB_USER" \
    -d "$DB_NAME" \
    --clean \
    --if-exists \
    "$DUMP_FILE" || true
else
  echo "❌ Error: Neither 'homeseva_postgres' container nor POSTGRES_PASSWORD is available."
  exit 1
fi

echo "================================================================="
echo "✅ Database restore completed successfully."
echo "================================================================="
